:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e8e8f0;
  --text-muted: #8a8ab0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --accent-pressed: #c73550;
  --swatch-radius: 12px;
  --focus-ring: 0 0 0 3px #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 32px 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

header {
  text-align: center;
  margin-bottom: 28px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-bottom: 28px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.swatch-color {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--swatch-radius);
  border: 2px solid rgba(255, 255, 255, 0.08);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.swatch-color:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
}

.hex-code {
  font-family: 'SF Mono', 'Cascadia Code', Consolas, monospace;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--text);
  user-select: all;
}

.lock-btn {
  background: transparent;
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 4px 8px;
  cursor: pointer;
  transition: all 0.15s ease;
  line-height: 1;
  min-width: 36px;
  min-height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lock-btn:hover {
  border-color: var(--accent);
  color: var(--text);
  background: rgba(233, 69, 96, 0.1);
}

.lock-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn[aria-pressed="true"] {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(233, 69, 96, 0.15);
}

.generate-btn {
  display: block;
  width: 100%;
  padding: 16px 24px;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  letter-spacing: 0.01em;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

@media (max-width: 420px) {
  .card {
    padding: 24px 16px;
    border-radius: 16px;
  }

  .palette {
    grid-template-columns: repeat(5, 1fr);
    gap: 6px;
  }

  .hex-code {
    font-size: 0.65rem;
  }

  .lock-btn {
    font-size: 0.75rem;
    padding: 3px 4px;
    min-width: 28px;
    min-height: 28px;
  }

  h1 {
    font-size: 1.4rem;
  }
}

(function () {
  'use strict';

  var paletteEl = document.getElementById('palette');
  var generateBtn = document.getElementById('generateBtn');
  var SWATCH_COUNT = 5;
  var locked = [false, false, false, false, false];
  var colors = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;
    if (h < 60) { r = c; g = x; }
    else if (h < 120) { r = x; g = c; }
    else if (h < 180) { g = c; b = x; }
    else if (h < 240) { g = x; b = c; }
    else if (h < 300) { r = x; b = c; }
    else { r = c; b = x; }
    r = Math.round((r + m) * 255);
    g = Math.round((g + m) * 255);
    b = Math.round((b + m) * 255);
    return '#' + [r, g, b].map(function (v) {
      return v.toString(16).padStart(2, '0');
    }).join('');
  }

  function generateHarmoniousPalette() {
    var baseHue = Math.random() * 360;
    var scheme = Math.floor(Math.random() * 3);
    var hues = [];
    var i;
    if (scheme === 0) {
      for (i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + i * 72) % 360);
      }
    } else if (scheme === 1) {
      var offsets = [0, 30, 60, 180, 210];
      for (i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + offsets[i]) % 360);
      }
    } else {
      var triad = [0, 120, 240];
      for (i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + triad[i % 3] + (i >= 3 ? 15 : 0)) % 360);
      }
    }
    var sat = 55 + Math.random() * 25;
    var lightBase = 45 + Math.random() * 15;
    return hues.map(function (h, idx) {
      var l = lightBase + (idx % 2 === 0 ? 8 : -8);
      l = Math.max(30, Math.min(70, l));
      return hslToHex(h, sat, l);
    });
  }

  function render() {
    paletteEl.innerHTML = '';
    colors.forEach(function (hex, idx) {
      var swatch = document.createElement('div');
      swatch.className = 'swatch';

      var colorBox = document.createElement('div');
      colorBox.className = 'swatch-color';
      colorBox.style.backgroundColor = hex;
      colorBox.setAttribute('aria-hidden', 'true');

      var hexLabel = document.createElement('span');
      hexLabel.className = 'hex-code';
      hexLabel.textContent = hex;

      var lockBtn = document.createElement('button');
      lockBtn.className = 'lock-btn';
      lockBtn.type = 'button';
      lockBtn.setAttribute('aria-pressed', locked[idx] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', (locked[idx] ? 'Unlock' : 'Lock') + ' color ' + hex);
      lockBtn.textContent = locked[idx] ? '\uD83D\uDD12' : '\uD83D\uDD13';

      lockBtn.addEventListener('click', (function (i) {
        return function () {
          locked[i] = !locked[i];
          render();
        };
      })(idx));

      swatch.appendChild(colorBox);
      swatch.appendChild(hexLabel);
      swatch.appendChild(lockBtn);
      paletteEl.appendChild(swatch);
    });
  }

  function regenerate() {
    var fresh = generateHarmoniousPalette();
    colors = colors.map(function (hex, idx) {
      return locked[idx] ? hex : fresh[idx];
    });
    render();
  }

  colors = generateHarmoniousPalette();
  render();

  generateBtn.addEventListener('click', regenerate);
})();
